    const LABELS = (() => {
      const map = Object.create(null);
      for (const row of LAYOUT) for (const key of row) map[key.code] = key.label;
      return map;
    })();

    const HIST_BUCKETS = 25;
    const HIST_STEP = 10;
    const SAMPLES_MAX = 2000;
    const RATE_WINDOW_MS = 10000;

    /* -------------------------------------------------------------- 工具 */

    function clamp(value, low, high) {
      return value < low ? low : value > high ? high : value;
    }

    function finite(value) {
      return typeof value === 'number' && Number.isFinite(value);
    }

    function now() {
      return typeof performance !== 'undefined' && performance && finite(performance.now())
        ? performance.now()
        : Date.now();
    }

    /** 优先用事件自带的高精度时间戳（更接近内核收到中断的时刻）。 */
    function stampOf(event) {
      const own = event && event.timeStamp;
      if (finite(own) && own > 0 && Math.abs(own - now()) < 5000) return own;
      return now();
    }

    function round(value, digits) {
      if (!finite(value)) return 0;
      const scale = Math.pow(10, digits === undefined ? 0 : digits);
      return Math.round(value * scale) / scale;
    }

