          state.dwellSum += dwell;
          state.dwellSqSum += dwell * dwell;
          if (dwell > state.dwellMax) state.dwellMax = dwell;
          stat.typed += 1;
          stat.sum += dwell;
          stat.sq += dwell * dwell;
