    /* @sfx-end */
    const SFX_MAX_VOICES = 18;
    const SFX_MIN_GAP_MS = 22;
    const SFX_SUSPEND_MS = 2500;

    /**
     * 氛围层：几十秒的**原始全长录音**（空袭警报 / B-25 起飞 / 电台通话），
     * 不做切片 —— 切片会把它们的"过程感"（警报升调、飞机由远及近）切没。
     *
     * 但它们不能每键一发，所以只在三种时机按下：
     *   siren  静默 20 秒后重新开始打字（"回到战场"）
     *   plane  持续打字 90–150 秒才可能掠过一架
     *   radio  手速 ≥6 键/秒时偶尔漏出一句
     * 播放时只是从原始录音里取一个窗口（start(when, offset, duration)），
     * 波形本身还是原文件，所以体积只有一份。
     *
     * 这三个池**不参与启动解码**（53 秒的警报解一遍要几十毫秒、几 MB 内存），
     * 第一次真正要用时才解码。
     */
    const AMBIENCE_POOLS = ['siren', 'plane', 'radio'];
    const SFX_RETURN_IDLE_MS = 20000;
    const SFX_SIREN_GAP_MS = 60000;
    const SFX_PLANE_MIN_MS = 90000;
    const SFX_PLANE_JIT_MS = 60000;
    const SFX_RADIO_MIN_MS = 8000;
    /**
     * 软削波参数的由来（实测，12 发错开 90ms 的衰减噪声，单发峰值 0.89）：
     * - 天花板 CEILING 0.90：整条链的峰值上限，留 1dB 余量给采样间峰值（真机 DAC 重建会略超采样点）。
     * - 输入域 RANGE 4：Web Audio 的 WaveShaper 只认 ±1 的曲线定义域，超过就钉在端点（等于硬削波）。
     *   主链 master 最高 3.2 × 声部峰值 1.2 ≈ 3.8，所以先把信号除以 4 压进定义域，曲线再按同一比例还原。
     * - oversample 用 'none'：4x 的上/下采样滤波器会振铃，实测把峰值从 0.88 顶到 1.078（反而削波），
     *   而不做软削波时削波的是原始信号。省 CPU 也更干净。
     */
    const SFX_CLIP_CEILING = 0.9;
    const SFX_CLIP_RANGE = 4;
    // 混响：一条共享的「空间」总线。单个击键只有 240–320ms，那本来就是「啪」；
    // 让人觉得「像鞭炮」的不是音量，而是每一发都在同一瞬间干净地消失。
    //
    // 分寸很重要：第一版给的是一条 1.15 秒、衰减 2.2 的湿声（send 0.3 / wet 0.5），
    // 听感直接变成「空旷大厅」—— 那不像在甲板上开炮，像在教堂里。所以：
    //   · 时长砍到 0.55 秒、衰减提到 3.2（尾巴更陡，等于更小的房间，不是更长的走廊）
    //   · 送出量 0.3 → 0.12、湿声 0.5 → 0.26（让长尾层 boom 去承担"厚"，混响只负责"同一个空间"）
    //   · 湿声再串一个 3.2kHz 低通（真实房间的尾巴是暗的，亮尾巴会像金属罐）
    // 现在的定位：混响是黏合剂，不是主角。
    const SFX_REVERB_SECONDS = 0.55;
    const SFX_REVERB_DECAY = 3.2;
    const SFX_REVERB_SEND = 0.12;
    const SFX_REVERB_WET = 0.26;
    const SFX_REVERB_TONE = 3200;
    // 火力档位：同一套素材，靠「叠层密度 + 主链响度 + 压缩」三件事决定激烈程度。
    // 单纯加 gain 只会削波变糊；推 master 再上压缩器，才既有冲击力又不炸。
    // tail / tailGain 是「长尾层」的概率与增益：接在每一发之后的低频轰鸣。
    const SFX_PRESETS = [
      { name: '标准', boom: 92, boomVoices: 2, boomGain: 0.3, tail: 0.45, tailGain: 0.22, long: 0.25, far: 4, farMin: 2000, farMax: 4600, farGain: 0.15, echo: 0.22, master: 2.0, burst: 0 },
      { name: '激烈', boom: 82, boomVoices: 3, boomGain: 0.44, tail: 0.60, tailGain: 0.30, long: 0.45, far: 3, farMin: 1300, farMax: 3000, farGain: 0.24, echo: 0.38, master: 2.6, burst: 0.25 },
      { name: '失控', boom: 72, boomVoices: 4, boomGain: 0.55, tail: 0.75, tailGain: 0.36, long: 0.65, far: 2, farMin: 800, farMax: 2000, farGain: 0.34, echo: 0.55, master: 3.2, burst: 0.45 },
    ];
    const SFX_DEFAULT_PRESET = 1;
    /** 只接受 0/1/2，越界就夹到边界 —— 老版本存下的脏值不该让引擎崩。 */
    function presetIndexOf(value) {
      const n = finite(value) ? Math.round(value) : SFX_DEFAULT_PRESET;
      if (n < 0) return 0;
      return n > SFX_PRESETS.length - 1 ? SFX_PRESETS.length - 1 : n;
    }
    function voiceCap(presetIndex) {
      return SFX_MAX_VOICES + presetIndex * 3;
    }

