    // 火力三档是「粗调」，这里是「细调」：不填（null）就跟随当前档位，
    // 拖动滑块才写进覆盖值，所以档位和手调的语义不会互相打架。
    const TUNE_KEY = 'dsh-battlefield.tune.v1';
    const TUNE_SPECS = [
      { key: 'space', labelKey: 'tuneSpace', min: 0, max: 200, step: 5, unitKey: 'unitPercent', fallback: 100,
        hintKey: 'tuneSpaceHint', tipKey: 'tuneSpaceTip' },
      { key: 'tail', labelKey: 'tuneTail', min: 0, max: 100, step: 1, unitKey: 'unitPercent', fallback: null,
        hintKey: 'tuneTailHint', tipKey: 'tuneTailTip' },
      { key: 'long', labelKey: 'tuneLong', min: 0, max: 100, step: 1, unitKey: 'unitPercent', fallback: null,
        hintKey: 'tuneLongHint', tipKey: 'tuneLongTip' },
      { key: 'echo', labelKey: 'tuneEcho', min: 0, max: 100, step: 1, unitKey: 'unitPercent', fallback: null,
        hintKey: 'tuneEchoHint', tipKey: 'tuneEchoTip' },
      { key: 'burst', labelKey: 'tuneBurst', min: 0, max: 100, step: 1, unitKey: 'unitPercent', fallback: null,
        hintKey: 'tuneBurstHint', tipKey: 'tuneBurstTip' },
      { key: 'boom', labelKey: 'tuneBoom', min: 1, max: 99, step: 1, unitKey: 'unitScore', fallback: null,
        hintKey: 'tuneBoomHint', tipKey: 'tuneBoomTip' },
      { key: 'gap', labelKey: 'tuneGap', min: 0, max: 150, step: 1, unitKey: 'unitMs', fallback: null,
        hintKey: 'tuneGapHint', tipKey: 'tuneGapTip' },
      { key: 'bed', labelKey: 'tuneBed', min: 0, max: 200, step: 5, unitKey: 'unitPercent', fallback: 100,
        hintKey: 'tuneBedHint', tipKey: 'tuneBedTip' },
    ];
    const TUNE_BY_KEY = Object.create(null);
    for (const spec of TUNE_SPECS) TUNE_BY_KEY[spec.key] = spec;
    /** 把存下来的脏值夹回合法区间，非法项直接丢掉。 */
    function sanitizeTune(raw) {
      const out = Object.create(null);
      if (!raw || typeof raw !== 'object') return out;
      for (const spec of TUNE_SPECS) {
        if (!finite(raw[spec.key])) continue;
        out[spec.key] = clamp(Math.round(raw[spec.key]), spec.min, spec.max);
      }
      return out;
    }


